469	  // ---------- 普通交易分阶段审批（签名收集与提交分离；旧入口行为不变） ----------
470	
471	  /**
472	   * 创建一笔普通交易的分阶段审批：只校验并登记，不消费 nonce、不建任务、不改策略。
473	   *
474	   * 审批摘要用 safe-wallet/tx-approval/v1 域，绑定钱包标识、创建时策略版本与完整交易字段
475	   * （data 复制保存），与直接提交的 safe-wallet/tx/v1 摘要互不通用。
476	   *
477	   * 校验顺序与 submitTransaction 一致（失败不产生任何状态变化）：
478	   *   1) nonce 复用 → NonceAlreadyUsedError
479	   *   2) deadline 早于当前时间 → RequestExpired
480	   *   3) 字段非法或 nonce 跳号（须等于 expectedNonce）→ InvalidTransaction
481	   *
482	   * 成功时返回审批快照（标识、摘要、版本、确认数、空签名者列表、collecting 状态）。
483	   */
484	  createTransactionApproval(sub: TransactionSubmission): TransactionApproval {
485	    // (1) nonce 安全转换与复用判定（复用优先于过期，与既有提交一致）
486	    const nonce = toBigInt(sub.nonce, InvalidTransaction, 'nonce');
487	    if (!isNonNegativeInteger(nonce)) throw new InvalidTransaction('nonce must be a non-negative integer');
488	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
489	
490	    // (2) 截止时间
491	    const deadline = toBigInt(sub.deadline, InvalidTransaction, 'deadline');
492	    if (!isNonNegativeInteger(deadline)) throw new InvalidTransaction('deadline out of range');
493	    if (deadline < this.now()) {
494	      throw new RequestExpired(`request deadline ${deadline} already passed`);
495	    }
496	    // (3) nonce 顺序：创建只登记不消费，但仍须绑定当前期望 nonce（跳号即非法）
497	    if (nonce !== this.nextNonce) {
498	      throw new InvalidTransaction(`expected nonce ${this.nextNonce}, got ${nonce}`);
499	    }
500	
501	    // (4) 交易字段校验与规范化（与直接提交同一套规则）
502	    const to = normalizeAddress(sub.to);
503	    if (to === null || isZeroAddress(to)) throw new InvalidTransaction('invalid or zero recipient address');
504	    const value = toBigInt(sub.value, InvalidTransaction, 'value');
505	    if (!isNonNegativeInteger(value)) throw new InvalidTransaction('value out of range');
506	    const dataField = sub.data;
507	    if (dataField !== undefined && !(dataField instanceof Uint8Array) && !ArrayBuffer.isView(dataField)) {
508	      throw new InvalidTransaction('data must be a byte array');
509	    }
510	    // 复制一份，避免创建后调用方改动同一缓冲区影响审批内容/摘要
511	    const data = Buffer.from((dataField as Uint8Array | undefined) ?? new Uint8Array());
512	
513	    const req: TransactionApprovalRequest = {
514	      walletId: this.id,
515	      version: this.version,
516	      nonce,
517	      deadline,
518	      to,
519	      value,
520	      data,
521	    };
522	    const digest = hashTransactionApproval(req);
523	    const id = createHash('sha256')
524	      .update(`approval:${this.approvalSeq}:${digest.toString('hex')}`)
525	      .digest('hex')
526	      .slice(0, 16);
527	    this.approvalSeq += 1;
528	
529	    const record: ApprovalRecord = {
530	      id,
531	      digest,
532	      version: this.version,
533	      confirmations: this.confirmations,
534	      nonce,
535	      deadline,
536	      to,
537	      value,
538	      data,
539	      signers: [],
540	      signatures: new Map(),
541	      submitted: false,
542	    };
543	    this.approvals.set(id, record);
544	    return this.approvalSnapshot(record);
545	  }
