1	import { generateKeyPair, signDigest, sha256, type Address, type KeyPair } from '../src/crypto.ts';
2	import {
3	  hashCancellation,
4	  hashPolicyChange,
5	  hashPolicyApproval,
6	  hashTransaction,
7	  hashTransactionApproval,
8	  hashTransactionBatch,
9	} from '../src/encoding.ts';
10	
11	export interface Actor extends KeyPair {}
12	
13	export function actors(n: number): Actor[] {
14	  return Array.from({ length: n }, () => generateKeyPair());
15	}
16	
17	export function addresses(list: Actor[]): Address[] {
18	  return list.map((a) => a.address);
19	}
20	
21	/** 可控时钟 */
22	export function fakeClock(start = 1000n): { now: () => bigint; advance: (s: bigint) => void; set: (t: bigint) => void } {
23	  let t = start;
24	  return {
25	    now: () => t,
26	    advance: (s: bigint) => {
27	      t += s;
28	    },
29	    set: (v: bigint) => {
30	      t = v;
31	    },
32	  };
33	}
34	
35	export interface TxParams {
36	  walletId: string;
37	  nonce: bigint;
38	  deadline: bigint;
39	  to: Address;
40	  value?: bigint;
41	  data?: Uint8Array;
42	}
43	
44	export function signTransaction(
45	  signers: Actor[],
46	  p: TxParams,
47	  opts: { mutate?: (base: TxParams) => TxParams } = {},
48	): Buffer[] {
49	  const base: TxParams = {
50	    walletId: p.walletId,
51	    nonce: p.nonce,
52	    deadline: p.deadline,
53	    to: p.to,
54	    value: p.value ?? 0n,
55	    data: p.data ?? new Uint8Array(),
56	  };
57	  const finalParams = opts.mutate ? opts.mutate(base) : base;
58	  const digest = hashTransaction({
59	    ...finalParams,
60	    value: finalParams.value ?? 0n,
61	    data: finalParams.data ?? new Uint8Array(),
62	  });
63	  return signers.map((s) => signDigest(s.privateKey, digest));
64	}
65	
66	export interface PcParams {
67	  walletId: string;
68	  version: bigint;
69	  nonce: bigint;
70	  deadline: bigint;
71	  newOwners: Address[];
72	  newConfirmations: bigint;
73	}
74	
75	export function signPolicyChange(
76	  signers: Actor[],
77	  p: PcParams,
78	  opts: { mutate?: (base: PcParams) => PcParams } = {},
79	): Buffer[] {
80	  const finalParams = opts.mutate ? opts.mutate(p) : p;
81	  const digest = hashPolicyChange(finalParams);
82	  return signers.map((s) => signDigest(s.privateKey, digest));
83	}
84	
85	export interface CancelParams {
86	  walletId: string;
87	  /** 目标任务的 digest（hex） */
88	  taskDigest: string;
89	  nonce: bigint;
90	  deadline: bigint;
91	}
92	
93	export function signCancellation(
94	  signers: Actor[],
95	  p: CancelParams,
96	  opts: { mutate?: (base: CancelParams) => CancelParams } = {},
97	): Buffer[] {
98	  const finalParams = opts.mutate ? opts.mutate(p) : p;
99	  const digest = hashCancellation(finalParams);
100	  return signers.map((s) => signDigest(s.privateKey, digest));
101	}
102	
103	export interface BatchCallParams {
104	  to: Address;
105	  value?: bigint;
106	  data?: Uint8Array;
107	}
108	
109	export interface BatchParams {
110	  walletId: string;
111	  nonce: bigint;
112	  deadline: bigint;
113	  calls: BatchCallParams[];
114	}
115	
116	export function signBatchTransaction(
117	  signers: Actor[],
118	  p: BatchParams,
119	  opts: { mutate?: (base: BatchParams) => BatchParams } = {},
120	): Buffer[] {
121	  const normalize = (q: BatchParams) => ({
122	    walletId: q.walletId,
123	    nonce: q.nonce,
124	    deadline: q.deadline,
125	    calls: q.calls.map((c) => ({
126	      to: c.to,
127	      value: c.value ?? 0n,
128	      data: c.data ?? new Uint8Array(),
129	    })),
130	  });
131	  const finalParams = opts.mutate ? opts.mutate(p) : p;
132	  const digest = hashTransactionBatch(normalize(finalParams));
133	  return signers.map((s) => signDigest(s.privateKey, digest));
134	}
135	
136	export interface ApprovalParams {
137	  walletId: string;
138	  version: bigint;
139	  nonce: bigint;
140	  deadline: bigint;
141	  to: Address;
142	  value?: bigint;
143	  data?: Uint8Array;
144	}
145	
146	export function signTransactionApproval(
147	  signers: Actor[],
148	  p: ApprovalParams,
149	  opts: { mutate?: (base: Required<ApprovalParams>) => ApprovalParams } = {},
150	): Buffer[] {
151	  const base: Required<ApprovalParams> = {
152	    walletId: p.walletId,
153	    version: p.version,
154	    nonce: p.nonce,
