29	const WALLET = 'wallet-policy-approval';
30	
31	function setup(ownerCount = 3, confirmations = 2n, start = 1000n) {
32	  const ownerActors = actors(ownerCount);
33	  const clock = fakeClock(start);
34	  const wallet = new MultiSigWallet({
35	    id: WALLET,
36	    owners: addresses(ownerActors),
