38	    now: clock.now,
39	  });
40	  return { ownerActors, clock, wallet };
41	}
42	
43	const newbie = generateKeyPair();
44	
45	type PolicyInput = {
46	  version: bigint;
47	  nonce: bigint;
48	  deadline: bigint;
49	  newOwners: string[];
50	  newConfirmations: bigint;
51	};
52	
53	function policyInput(ownerActors: Actor[], overrides: Partial<PolicyInput> = {}): PolicyInput {
54	  return {
55	    version: 1n,
56	    nonce: 0n,
57	    deadline: 9000n,
58	    newOwners: addresses(ownerActors),
59	    newConfirmations: 2n,
60	    ...overrides,
61	  };
62	}
63	
64	function policySigs(ownerActors: Actor[], input: PolicyInput, count = 2) {
65	  return signPolicyApproval(ownerActors.slice(0, count), {
66	    walletId: WALLET,
67	    ...input,
68	  });
69	}
