84	  });
85	
86	  const a = wallet.createPolicyApproval(input);
87	  assert.equal(typeof a.id, 'string');
88	  assert.ok(a.id.length > 0);
89	  assert.equal(a.version, 1n);
90	  assert.equal(a.confirmations, 2n); // 创建时的当前确认数
91	  assert.equal(a.nonce, 0n);
92	  assert.equal(a.deadline, 9000n);
93	  assert.deepEqual(a.newOwners, [ownerActors[0]!.address, newbie.address]);
94	  assert.equal(a.newConfirmations, 1n);
95	  assert.deepEqual(a.signers, []);
96	  assert.equal(a.status, 'collecting');
97	
98	  // 摘要与 safe-wallet/policy-change-approval/v1 域一致
99	  const expected = hashPolicyApproval({ walletId: WALLET, ...input });
100	  assert.equal(a.digest, expected.toString('hex'));
101	  // 与直接提交的 safe-wallet/policy-change/v1 摘要不同
102	  const directDigest = hashPolicyChange({ walletId: WALLET, ...input });
103	  assert.notEqual(a.digest, directDigest.toString('hex'));
104	
105	  // 登记不产生任何既有状态变化
106	  assert.equal(wallet.expectedNonce, before.nonce);
107	  assert.equal(wallet.isNonceUsed(0n), false);
108	  assert.equal(wallet.tasks.length, 0);
