112	});
113	
114	test('创建策略审批：新所有者顺序参与摘要绑定，顺序不同摘要不同', () => {
115	  const { wallet, ownerActors } = setup();
116	  const a = wallet.createPolicyApproval(
117	    policyInput(ownerActors, { newOwners: [ownerActors[0]!.address, ownerActors[1]!.address] }),
118	  );
