126	test('创建策略审批：同一 nonce 可登记多个候选（创建不消费 nonce），标识各不相同', () => {
127	  const { wallet, ownerActors } = setup();
128	  const a = wallet.createPolicyApproval(policyInput(ownerActors));
129	  const b = wallet.createPolicyApproval(
130	    policyInput(ownerActors, { newOwners: [ownerActors[0]!.address, newbie.address], newConfirmations: 1n }),
