141	test('创建策略审批：目标策略字段非法或版本不匹配抛 InvalidPolicyChange，失败不变', () => {
142	  const { wallet, ownerActors } = setup();
143	  const base = policyInput(ownerActors);
144	
145	  // 新所有者为空
146	  assert.throws(
147	    () => wallet.createPolicyApproval({ ...base, newOwners: [] }),
148	    InvalidPolicyChange,
149	  );
150	  // 重复所有者
151	  assert.throws(
152	    () =>
153	      wallet.createPolicyApproval({
154	        ...base,
155	        newOwners: [ownerActors[0]!.address, ownerActors[0]!.address],
156	      }),
157	    InvalidPolicyChange,
158	  );
159	  // 零地址
160	  assert.throws(
161	    () =>
162	      wallet.createPolicyApproval({
163	        ...base,
164	        newOwners: [ownerActors[0]!.address, '0x' + '00'.repeat(20)],
165	      }),
166	    InvalidPolicyChange,
167	  );
168	  // 非法地址
169	  assert.throws(
170	    () => wallet.createPolicyApproval({ ...base, newOwners: ['0x1234'] }),
171	    InvalidPolicyChange,
172	  );
173	  // 确认数为 0 / 超过新所有者数量
174	  assert.throws(
175	    () => wallet.createPolicyApproval({ ...base, newConfirmations: 0n }),
176	    InvalidPolicyChange,
177	  );
178	  assert.throws(
179	    () =>
180	      wallet.createPolicyApproval({
181	        ...base,
182	        newOwners: [ownerActors[0]!.address],
