227	// ---------- 加签 ----------
228	
229	test('策略审批加签：逐个收集当前所有者签名，达到阈值后 ready，签名者按加签顺序', () => {
230	  const { wallet, ownerActors } = setup();
231	  const input = policyInput(ownerActors);
232	  const a = wallet.createPolicyApproval(input);
233	  const sigs = policySigs(ownerActors, input, 2);
234	
235	  const mid = wallet.addPolicyApprovalSignature(a.id, sigs[0]!);
236	  assert.equal(mid.status, 'collecting');
237	  assert.deepEqual(mid.signers, [ownerActors[0]!.address]);
