239	  const ready = wallet.addPolicyApprovalSignature(a.id, sigs[1]!);
240	  assert.equal(ready.status, 'ready');
241	  assert.deepEqual(ready.signers, [ownerActors[0]!.address, ownerActors[1]!.address]);
242	
243	  // 加签不改策略、nonce、队列
