265	test('策略审批加签：格式非法、摘要不符或签名者非所有者抛 InvalidApprovalSignatureError', () => {
266	  const { wallet, ownerActors } = setup();
267	  const input = policyInput(ownerActors);
268	  const a = wallet.createPolicyApproval(input);
269	  const sigs = policySigs(ownerActors, input, 2);
270	
271	  // 非 65 字节
272	  assert.throws(
273	    () => wallet.addPolicyApprovalSignature(a.id, new Uint8Array(64)),
274	    InvalidApprovalSignatureError,
275	  );
