305	
306	test('策略审批签名不能用于直接 proposePolicyChange（两域互不通用）', () => {
307	  const { wallet, ownerActors } = setup();
308	  const input = policyInput(ownerActors);
309	  const a = wallet.createPolicyApproval(input);
310	  const sigs = policySigs(ownerActors, input, 2);
311	  wallet.addPolicyApprovalSignature(a.id, sigs[0]!);
312	  wallet.addPolicyApprovalSignature(a.id, sigs[1]!);
313	  // 同一内容、同一批签名者：审批域签名无法授权直接提交
314	  assert.throws(() => wallet.proposePolicyChange(input, sigs), InvalidPolicyChange);
