316	});
317	
318	test('未知策略审批 id：加签 / 查询 / 提交均抛 ApprovalNotFoundError', () => {
319	  const { wallet, ownerActors } = setup();
320	  const sigs = policySigs(ownerActors, policyInput(ownerActors), 1);
321	  assert.throws(() => wallet.addPolicyApprovalSignature('nope', sigs[0]!), ApprovalNotFoundError);
322	  assert.throws(() => wallet.getPolicyApproval('nope'), ApprovalNotFoundError);
323	  assert.throws(() => wallet.submitApprovedPolicyChange('nope'), ApprovalNotFoundError);
324	});
325	
326	// ---------- 过期与版本漂移 ----------
327	
328	test('策略审批过期：加签 / 提交抛 ApprovalExpiredError，查询状态 expired', () => {
329	  const { wallet, ownerActors, clock } = setup();
330	  const input = policyInput(ownerActors, { deadline: 2000n });
331	  const a = wallet.createPolicyApproval(input);
332	  const sigs = policySigs(ownerActors, input, 2);
333	  wallet.addPolicyApprovalSignature(a.id, sigs[0]!);
334	  clock.set(2001n);
335	
336	  assert.throws(() => wallet.addPolicyApprovalSignature(a.id, sigs[1]!), ApprovalExpiredError);
337	  assert.throws(() => wallet.submitApprovedPolicyChange(a.id), ApprovalExpiredError);
338	  assert.equal(wallet.getPolicyApproval(a.id).status, 'expired');
339	  // 失败不变
340	  assert.equal(wallet.expectedNonce, 0n);
341	  assert.equal(wallet.tasks.length, 0);
342	});
343	
344	/** 通过直接策略变更让版本漂移（审批不消费 nonce，故用 nonce 0；版本 1 → 2） */
345	function driftPolicy(wallet: MultiSigWallet, ownerActors: Actor[]) {
346	  const input = policyInput(ownerActors);
347	  const sigs = signPolicyChange(ownerActors.slice(0, 2), { walletId: WALLET, ...input });
348	  const task = wallet.proposePolicyChange(input, sigs);
349	  wallet.executeTask(task.id);
350	  assert.equal(wallet.policyVersion, 2n);
351	}
352	
353	test('策略审批版本漂移：加签 / 提交抛 ApprovalPolicyConflictError，查询状态 conflicted', () => {
354	  const { wallet, ownerActors } = setup();
355	  const input = policyInput(ownerActors);
356	  const a = wallet.createPolicyApproval(input);
357	  const sigs = policySigs(ownerActors, input, 2);
358	  wallet.addPolicyApprovalSignature(a.id, sigs[0]!);
359	
360	  driftPolicy(wallet, ownerActors);
361	
362	  assert.throws(() => wallet.addPolicyApprovalSignature(a.id, sigs[1]!), ApprovalPolicyConflictError);
363	  assert.throws(() => wallet.submitApprovedPolicyChange(a.id), ApprovalPolicyConflictError);
364	  assert.equal(wallet.getPolicyApproval(a.id).status, 'conflicted');
