  return encBytes(Buffer.from(s, 'utf8'));
}

export function encUint(n: bigint | number): Buffer {
  const v = BigInt(n);
  if (v < 0n) throw new Error('cannot encode negative integer');
  if (v >> 256n !== 0n) throw new Error('integer exceeds 32 bytes');
